CREATE TABLE material (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,created_by BIGINT NULL,updated_by BIGINT NULL,version BIGINT NOT NULL DEFAULT 0,
 code VARCHAR(50) NOT NULL,name VARCHAR(120) NOT NULL,type VARCHAR(20) NOT NULL,unit VARCHAR(10) NOT NULL,specification VARCHAR(255) NOT NULL,min_stock DECIMAL(12,0) NOT NULL DEFAULT 0,enabled BOOLEAN NOT NULL,referenced BOOLEAN NOT NULL DEFAULT FALSE,
 UNIQUE KEY uq_material_code(code),KEY ix_material_type_enabled(type,enabled,id),CHECK(type IN('RAW_MATERIAL','FINISHED_GOOD')),CHECK(min_stock>=0),FOREIGN KEY(created_by) REFERENCES sys_user(id),FOREIGN KEY(updated_by) REFERENCES sys_user(id),CHECK(version>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE customer (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,created_by BIGINT NULL,updated_by BIGINT NULL,version BIGINT NOT NULL DEFAULT 0,code VARCHAR(50) NOT NULL,name VARCHAR(120) NOT NULL,contact_name VARCHAR(80) NOT NULL,phone VARCHAR(40) NOT NULL,address VARCHAR(255) NOT NULL,enabled BOOLEAN NOT NULL,UNIQUE KEY uq_customer_code(code),KEY ix_customer_enabled(enabled,id),FOREIGN KEY(created_by) REFERENCES sys_user(id),FOREIGN KEY(updated_by) REFERENCES sys_user(id),CHECK(version>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE supplier (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,created_by BIGINT NULL,updated_by BIGINT NULL,version BIGINT NOT NULL DEFAULT 0,code VARCHAR(50) NOT NULL,name VARCHAR(120) NOT NULL,contact_name VARCHAR(80) NOT NULL,phone VARCHAR(40) NOT NULL,address VARCHAR(255) NOT NULL,enabled BOOLEAN NOT NULL,UNIQUE KEY uq_supplier_code(code),KEY ix_supplier_enabled(enabled,id),FOREIGN KEY(created_by) REFERENCES sys_user(id),FOREIGN KEY(updated_by) REFERENCES sys_user(id),CHECK(version>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE warehouse (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,created_by BIGINT NULL,updated_by BIGINT NULL,version BIGINT NOT NULL DEFAULT 0,code VARCHAR(50) NOT NULL,name VARCHAR(120) NOT NULL,address VARCHAR(255) NOT NULL,enabled BOOLEAN NOT NULL,UNIQUE KEY uq_warehouse_code(code),KEY ix_warehouse_enabled(enabled,id),FOREIGN KEY(created_by) REFERENCES sys_user(id),FOREIGN KEY(updated_by) REFERENCES sys_user(id),CHECK(version>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE bom (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,created_by BIGINT NULL,updated_by BIGINT NULL,version BIGINT NOT NULL DEFAULT 0,code VARCHAR(50) NOT NULL,name VARCHAR(120) NOT NULL,product_material_id BIGINT NOT NULL,revision INT NOT NULL DEFAULT 1,enabled BOOLEAN NOT NULL,
 enabled_product_id BIGINT GENERATED ALWAYS AS(CASE WHEN enabled THEN product_material_id ELSE NULL END) STORED,
 UNIQUE KEY uq_bom_code(code),UNIQUE KEY uq_bom_enabled_product(enabled_product_id),KEY ix_bom_product(product_material_id),FOREIGN KEY(product_material_id) REFERENCES material(id),CHECK(revision>0),FOREIGN KEY(created_by) REFERENCES sys_user(id),FOREIGN KEY(updated_by) REFERENCES sys_user(id),CHECK(version>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE bom_item (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,bom_id BIGINT NOT NULL,line_no INT NOT NULL,material_id BIGINT NOT NULL,quantity_per DECIMAL(12,0) NOT NULL,UNIQUE KEY uq_bom_item_material(bom_id,material_id),UNIQUE KEY uq_bom_line(bom_id,line_no),FOREIGN KEY(bom_id) REFERENCES bom(id),FOREIGN KEY(material_id) REFERENCES material(id),CHECK(quantity_per>0),CHECK(line_no>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
